insert into public.parameter_master(section_id,source_ref,source_file,source_serial,source_group,source_text,name,target_text,input_type,frequency,options,sort_order,source_review_required,description,mandatory,shift_applicability,product_code,active,alert_enabled,ticket_enabled)
select s.id,src.source_ref,'AGRO SAFETY POINTS.xlsx',src.source_serial,src.source_group,src.name,src.name,src.target_text,src.input_type,src.frequency,src.options,src.sort_order,src.source_review_required,src.description,true,'[1,2,3]'::jsonb,'PLANT',true,true,true
from src join public.parameter_sections s on s.module=src.module and s.name=src.section_name
where not exists(select 1 from public.parameter_master p where p.source_ref=src.source_ref
 or (p.section_id=s.id and regexp_replace(upper(p.name),'[^A-Z0-9]','','g')=regexp_replace(upper(src.name),'[^A-Z0-9]','','g')));
commit;
select s.module,s.name,count(*) as added_points from public.parameter_master p join public.parameter_sections s on s.id=p.section_id
where p.source_ref like 'AGRO_ADDITIONS_V84:%' group by s.module,s.name order by s.module,s.name;
